def normv(v):
    n = (v[0]**2 + v[1]**2 + v[2]**2) ** 0.5
    if n < 1e-12:
        return [0.0, 0.0, 0.0]
    return [v[0]/n, v[1]/n, v[2]/n]

def normq(q):
    n = (q[0]**2 + q[1]**2 + q[2]**2 + q[3]**2) ** 0.5
    return [q[0]/n, q[1]/n, q[2]/n, q[3]/n]

def dot3(a, b):
    return a[0]*b[0] + a[1]*b[1] + a[2]*b[2]

def cross3(a, b):
    return [a[1]*b[2]-a[2]*b[1], a[2]*b[0]-a[0]*b[2], a[0]*b[1]-a[1]*b[0]]

def mat2quat(x, y, z):
    m00, m10, m20 = x[0], x[1], x[2]
    m01, m11, m21 = y[0], y[1], y[2]
    m02, m12, m22 = z[0], z[1], z[2]
    tr = m00 + m11 + m22
    if tr > 0:
        s = (tr + 1.0) ** 0.5 * 2.0
        w = 0.25 * s; qx = (m21 - m12) / s; qy = (m02 - m20) / s; qz = (m10 - m01) / s
    elif m00 > m11 and m00 > m22:
        s = (1.0 + m00 - m11 - m22) ** 0.5 * 2.0
        w = (m21 - m12) / s; qx = 0.25 * s; qy = (m01 + m10) / s; qz = (m02 + m20) / s
    elif m11 > m22:
        s = (1.0 + m11 - m00 - m22) ** 0.5 * 2.0
        w = (m02 - m20) / s; qx = (m01 + m10) / s; qy = 0.25 * s; qz = (m12 + m21) / s
    else:
        s = (1.0 + m22 - m00 - m11) ** 0.5 * 2.0
        w = (m10 - m01) / s; qx = (m02 + m20) / s; qy = (m12 + m21) / s; qz = 0.25 * s
    return normq([qx, qy, qz, w])

