LLEN = 0.1698

def lid_pose(cosf, sinf, off):
    n = [-FDIR[0]*sinf, -FDIR[1]*sinf, cosf]
    p = [HINGE[0] + LLEN*cosf*FDIR[0] + off*n[0],
         HINGE[1] + LLEN*cosf*FDIR[1] + off*n[1],
         HINGE[2] + LLEN*sinf + off*cosf]
    zee = normv([-n[0], -n[1], -n[2]])
    xee = normv([XBX[0] - dot3(XBX, zee)*zee[0],
                 XBX[1] - dot3(XBX, zee)*zee[1],
                 XBX[2] - dot3(XBX, zee)*zee[2]])
    yee = cross3(zee, xee)
    return p + mat2quat(xee, yee, zee)

