    r = d * 3.141592653589793 / 180.0
    return r - r**3/6.0 + r**5/120.0 - r**7/5040.0 + r**9/362880.0

def cos_deg(d):
    r = d * 3.141592653589793 / 180.0
    return 1.0 - r**2/2.0 + r**4/24.0 - r**6/720.0 + r**8/40320.0

def asin_deg(x):
    lo, hi = 0.0, 90.0
    for _ in range(40):
        mid = 0.5*(lo+hi)
        if sin_deg(mid) < x:
            lo = mid
        else:
            hi = mid
    return 0.5*(lo+hi)

